  1→import React, { useState, useCallback, useEffect } from "react";
  2→import { useAuth } from "@/hooks/useAuth";
  3→import { supabase } from "@/integrations/supabase/client";
  4→import AppHeader from "@/components/AppHeader";
  5→import AuthDialog from "@/components/AuthDialog";
  6→import JobSidebar from "@/components/JobSidebar";
  7→import JobDetailView from "@/components/JobDetailView";
  8→import { SidebarProvider, SidebarTrigger, SidebarInset } from "@/components/ui/sidebar";
  9→import { Card, CardContent } from "@/components/ui/card";
 10→import { Button } from "@/components/ui/button";
 11→import { Badge } from "@/components/ui/badge";
 12→import { Plus, Briefcase, FileText, Zap, CheckCircle2 } from "lucide-react";
 13→import { toast } from "sonner";
 14→import { format } from "date-fns";
 15→
 16→export interface PastJob {
 17→  id: string;
 18→  title: string | null;
 19→  job_description: string;
 20→  status: string;
 21→  created_at: string;
 22→  resume_count: number;
 23→  jd_analysis_json: any;
 24→  dynamic_weights_json: Record<string, number> | null;
 25→  inbox_email: string | null;
 26→}
 27→
 28→export interface Result {
 29→  id: string;
 30→  resume_id: string;
 31→  overall_score: number;
 32→  missing_skills: string[];
 33→  summary: string | null;
 34→  interview_questions: any;
 35→  filename: string;
 36→  file_path: string | null;
 37→  candidate_name: string | null;
 38→  candidate_email?: string | null;
 39→  candidate_phone?: string | null;
 40→  candidate_location?: string | null;
 41→  // Dynamic scoring fields
 42→  hard_fit?: boolean;
 43→  category_scores_json?: Record<string, { score: number; evidence?: any[]; notes?: string }>;
 44→  confidence?: number;
 45→  strengths_json?: string[];
 46→  gaps_json?: string[];
 47→  explanation_json?: { summary?: string; why_ranked_here?: string; key_tradeoffs?: string; matched_preferred?: string[]; missing_preferred?: string[] };
 48→  matched_must_haves?: string[];
 49→  missing_must_haves?: string[];
 50→  scoring_version?: string;
 51→  pending?: boolean;
 52→  parsed_json?: any;
 53→}
 54→
 55→export interface ExistingResume {
 56→  id: string;
 57→  filename: string;
 58→  file_path: string | null;
 59→  candidate_name: string | null;
 60→  created_at: string;
 61→}
 62→
 63→const Index = () => {
 64→  const { user, profile } = useAuth();
 65→
 66→  const [pastJobs, setPastJobs] = useState<PastJob[]>([]);
 67→  const [selectedJobId, setSelectedJobId] = useState<string | null>(null);
 68→  const [showDashboard, setShowDashboard] = useState(true);
 69→  const [loadingPastJobs, setLoadingPastJobs] = useState(false);
 70→  const [results, setResults] = useState<Result[]>([]);
 71→  const [existingResumes, setExistingResumes] = useState<ExistingResume[]>([]);
 72→  const [authOpen, setAuthOpen] = useState(false);
 73→
 74→  const selectedJob = pastJobs.find((j) => j.id === selectedJobId) ?? null;
 75→
 76→  const fetchPastJobs = useCallback(async () => {
 77→    if (!user) return;
 78→    setLoadingPastJobs(true);
 79→    try {
 80→      const { data: jobs } = await supabase
 81→        .from("jobs")
 82→        .select("id, title, job_description, status, created_at, jd_analysis_json, dynamic_weights_json, inbox_email, resumes(count)")
 83→        .eq("user_id", user.id)
 84→        .order("created_at", { ascending: false })
 85→        .limit(50);
 86→      if (jobs) {
 87→        setPastJobs(jobs.map((j: any) => ({
 88→          id: j.id,
 89→          title: j.title,
 90→          job_description: j.job_description,
 91→          status: j.status,
 92→          created_at: j.created_at,
 93→          resume_count: j.resumes?.[0]?.count ?? 0,
 94→          jd_analysis_json: j.jd_analysis_json,
 95→          dynamic_weights_json: j.dynamic_weights_json,
 96→          inbox_email: j.inbox_email ?? null,
 97→        })));
 98→      }
 99→    } catch (err) {
100→      toast.error("Failed to load jobs");
101→    } finally {
102→      setLoadingPastJobs(false);
103→    }
104→  }, [user]);
105→
106→  useEffect(() => {
107→    fetchPastJobs();
108→  }, [fetchPastJobs]);
109→
110→  const loadJobData = async (jobId: string) => {
111→    setSelectedJobId(jobId);
112→    setShowDashboard(false);
113→    try {
114→      const [resumesRes, resumeListRes] = await Promise.all([
115→        supabase
116→          .from("resumes")
117→          .select("id, filename, file_path, candidate_name, created_at")
118→          .eq("job_id", jobId)
119→          .order("created_at", { ascending: false }),
120→        supabase
121→          .from("resumes")
122→          .select("id, filename, file_path, candidate_name, parsed_json")
123→          .eq("job_id", jobId),
124→      ]);
125→
126→      const resumes = resumesRes.data ?? [];
127→      setExistingResumes(resumes);
128→
129→      const resumeData = (resumeListRes.data ?? []) as Array<{
130→        id: string;
131→        filename: string;
132→        file_path: string | null;
133→        candidate_name: string | null;
134→        parsed_json?: any;
135→      }>;
136→      if (resumeData.length === 0) {
137→        setResults([]);
138→        return;
139→      }
140→
141→      const resumeIds = resumeData.map((r) => r.id);
142→      const { data: resultData } = await supabase
143→        .from("results")
144→        .select("id, resume_id, overall_score, missing_skills, summary, interview_questions, hard_fit, category_scores_json, confidence, strengths_json, gaps_json, explanation_json, matched_must_haves, missing_must_haves, scoring_version")
145→        .in("resume_id", resumeIds);
146→
147→      const resumeMap = new Map(resumeData.map((r) => [r.id, r]));
148→      const allMerged: Result[] = (resultData ?? []).map((r: any) => {
149→        const resume = resumeMap.get(r.resume_id);
150→        const parsed = resume?.parsed_json as any;
151→        return {
152→          ...r,
153→          overall_score: r.overall_score ?? 0,
154→          missing_skills: r.missing_skills ?? [],
155→          filename: resume?.filename ?? "Unknown",
156→          file_path: resume?.file_path ?? null,
157→          candidate_name: resume?.candidate_name ?? null,
158→          candidate_email: parsed?.email ?? parsed?.contact?.email ?? null,
159→          candidate_phone: parsed?.phone ?? parsed?.contact?.phone ?? null,
160→          candidate_location: parsed?.location ?? parsed?.contact?.location ?? null,
161→          parsed_json: resume?.parsed_json ?? null,
162→        };
163→      });
164→      // Deduplicate by resume_id — keep highest scoring result per resume
165→      const deduped = new Map<string, Result>();
166→      for (const r of allMerged) {
167→        const existing = deduped.get(r.resume_id);
168→        if (!existing || r.overall_score > existing.overall_score) {
169→          deduped.set(r.resume_id, r);
170→        }
171→      }
172→      const merged = Array.from(deduped.values());
173→      merged.sort((a, b) => b.overall_score - a.overall_score);
174→      setResults(merged);
175→    } catch (err) {
176→      toast.error("Failed to load job data");
177→    }
178→  };
179→
180→  const handleNewJob = () => {
181→    setSelectedJobId(null);
182→    setShowDashboard(false);
183→    setResults([]);
184→    setExistingResumes([]);
185→  };
186→
187→  const handleGoToDashboard = () => {
188→    setSelectedJobId(null);
189→    setShowDashboard(true);
190→    setResults([]);
191→    setExistingResumes([]);
192→  };
193→
194→  const handleJobCreated = (job: PastJob) => {
195→    setPastJobs((prev) => [job, ...prev]);
196→    setSelectedJobId(job.id);
197→    loadJobData(job.id);
198→  };
199→
200→  const handleRenameJob = (jobId: string, newTitle: string) => {
201→    setPastJobs((prev) =>
202→      prev.map((j) => (j.id === jobId ? { ...j, title: newTitle } : j))
203→    );
204→  };
205→
206→  const handleDeleteJob = async (jobId: string) => {
207→    try {
208→      await supabase.from("resumes").delete().eq("job_id", jobId);
209→      await supabase.from("jobs").delete().eq("id", jobId);
210→      setPastJobs((prev) => prev.filter((j) => j.id !== jobId));
211→      if (selectedJobId === jobId) handleNewJob();
212→      toast.success("Job deleted");
213→    } catch {
214→      toast.error("Failed to delete job");
215→    }
216→  };
217→
218→  const handleJobUpdated = (jobId: string, updates: Partial<PastJob>) => {
219→    setPastJobs((prev) =>
220→      prev.map((j) => (j.id === jobId ? { ...j, ...updates } : j))
221→    );
222→  };
223→
224→  const requireAuth = useCallback(() => {
225→    if (!user) { setAuthOpen(true); return true; }
226→    return false;
227→  }, [user]);
228→
229→  return (
230→    <SidebarProvider className="h-svh overflow-hidden">
231→      <JobSidebar
232→        pastJobs={pastJobs}
233→        selectedJobId={selectedJobId}
234→        showDashboard={showDashboard}
235→        loadingPastJobs={loadingPastJobs}
236→        onSelectJob={loadJobData}
237→        onNewJob={handleNewJob}
238→        onDashboard={handleGoToDashboard}
239→        onRenameJob={handleRenameJob}
240→        onDeleteJob={handleDeleteJob}
241→        onAuthRequired={() => setAuthOpen(true)}
242→        isAuthenticated={!!user}
243→      />
244→
245→      <SidebarInset className="h-svh overflow-y-auto">
246→        <AppHeader onLogoClick={user ? handleGoToDashboard : undefined} />
247→        <div className="flex items-center h-10 px-4 border-b border-border md:hidden">
248→          <SidebarTrigger />
249→          <span className="ml-2 text-sm font-medium text-muted-foreground">Job History</span>
250→        </div>
251→
252→        {/* Dashboard view */}
253→        {showDashboard && !selectedJobId && user ? (
254→          <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-6">
255→            {/* Greeting */}
256→            <div>
257→              <h1 className="text-xl font-semibold text-foreground">Welcome back</h1>
258→              <p className="text-sm text-muted-foreground mt-0.5">{user.email}</p>
259→            </div>
260→
261→            {/* Stats */}
262→            <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
263→              {[
264→                { label: "Jobs", value: pastJobs.length, icon: Briefcase },
265→                { label: "Resumes", value: pastJobs.reduce((s, j) => s + j.resume_count, 0), icon: FileText },
266→                { label: "Credits", value: (() => { const p = profile; if (!p) return 0; const s = (p.subscription_credits ?? 0) + (p.topup_credits ?? 0) + (p.bonus_credits ?? 0); return s > 0 ? s : (p.credits ?? 0); })(), icon: Zap },
267→                { label: "Completed", value: pastJobs.filter(j => j.status === "completed").length, icon: CheckCircle2 },
268→              ].map((s) => (
269→                <Card key={s.label}>
270→                  <CardContent className="px-4 py-3 flex items-center gap-3">
271→                    <div className="h-8 w-8 rounded-lg bg-muted flex items-center justify-center shrink-0">
272→                      <s.icon className="h-4 w-4 text-muted-foreground" />
273→                    </div>
274→                    <div>
275→                      <p className="text-xl font-semibold tabular-nums text-foreground">{s.value}</p>
276→                      <p className="text-xs text-muted-foreground">{s.label}</p>
277→                    </div>
278→                  </CardContent>
279→                </Card>
280→              ))}
281→            </div>
282→
283→            {/* Quick start */}
284→            <Button className="gap-2" onClick={handleNewJob}>
285→              <Plus className="h-4 w-4" /> Create New Job
286→            </Button>
287→
288→            {/* Recent jobs */}
289→            {pastJobs.length > 0 && (
290→              <div className="space-y-3">
291→                <h2 className="text-sm font-medium text-muted-foreground">Recent Jobs</h2>
292→                <div className="space-y-2">
293→                  {pastJobs.slice(0, 5).map((job) => (
294→                    <Card key={job.id} className="cursor-pointer hover:bg-muted/50 transition-colors" onClick={() => loadJobData(job.id)}>
295→                      <CardContent className="px-4 py-3 flex items-center justify-between">
296→                        <div className="min-w-0">
297→                          <p className="text-sm font-medium text-foreground truncate">{job.title || "Untitled Job"}</p>
298→                          <p className="text-xs text-muted-foreground mt-0.5">
299→                            {job.resume_count} resume{job.resume_count !== 1 ? "s" : ""} · {format(new Date(job.created_at), "MMM d, yyyy")}
300→                          </p>
301→                        </div>
302→                        <Badge variant={job.status === "completed" ? "secondary" : "outline"} className="shrink-0 capitalize text-xs">
303→                          {job.status}
304→                        </Badge>
305→                      </CardContent>
306→                    </Card>
307→                  ))}
308→                </div>
309→              </div>
310→            )}
311→
312→            {/* Getting started guide */}
313→            <Card>
314→              <CardContent className="px-5 py-4 space-y-3">
315→                <h2 className="text-sm font-medium text-foreground">Getting Started</h2>
316→                <div className="space-y-2.5">
317→                  {[
318→                    { step: "1", text: "Click \"Create New Job\" and paste a job description" },
319→                    { step: "2", text: "Upload candidate resumes (PDF, DOCX, or forward via email)" },
320→                    { step: "3", text: "AI ranks all candidates with scores, strengths, and gaps" },
321→                  ].map((item) => (
322→                    <div key={item.step} className="flex items-start gap-3 text-sm">
323→                      <span className="h-5 w-5 rounded-full bg-primary text-primary-foreground text-xs font-bold flex items-center justify-center shrink-0 mt-0.5">{item.step}</span>
324→                      <span className="text-muted-foreground">{item.text}</span>
325→                    </div>
326→                  ))}
327→                </div>
328→              </CardContent>
329→            </Card>
330→          </div>
331→        ) : (
332→          <JobDetailView
333→            selectedJobId={selectedJobId}
334→            selectedJob={selectedJob}
335→            results={results}
336→            setResults={setResults}
337→            existingResumes={existingResumes}
338→            setExistingResumes={setExistingResumes}
339→            onJobCreated={handleJobCreated}
340→            onAuthRequired={() => setAuthOpen(true)}
341→            isAuthenticated={!!user}
342→            pastJobs={pastJobs}
343→            onJobUpdated={handleJobUpdated}
344→          />
345→        )}
346→      </SidebarInset>
347→
348→      <AuthDialog open={authOpen} onOpenChange={setAuthOpen} defaultTab="signin" />
349→    </SidebarProvider>
350→  );
351→};
352→
353→export default Index;
